package handlers.skill.effects;

import org.l2jmobius.gameserver.entity.actor.Creature;
import org.l2jmobius.gameserver.entity.actor.Player;
import org.l2jmobius.gameserver.entity.item.instance.Item;
import org.l2jmobius.gameserver.mechanics.effects.AbstractEffect;
import org.l2jmobius.gameserver.mechanics.skill.Skill;
import org.l2jmobius.gameserver.util.StatSet;

/**
 * This effect handles the permanent modification of a character's {@code PK} count.<br>
 * It can be used to increase or decrease the count based on specific item effects.
 * @author Nik
 */
public class PkCount extends AbstractEffect
{
	private final int _amount;
	
	/**
	 * Creates a new {@code PkCount} effect.<br>
	 * This constructor initializes the amount to change.<br>
	 * It retrieves the value from the provided {@code StatSet}.
	 * @param params The {@code StatSet} containing the configuration values.
	 */
	public PkCount(StatSet params)
	{
		_amount = params.getInt("amount", 0);
	}
	
	/**
	 * Checks if the effect is applied instantly.<br>
	 * This method always returns {@code true}.
	 * @return {@code true} if the effect is instant.
	 */
	@Override
	public boolean isInstant()
	{
		return true;
	}
	
	/**
	 * Applies the effect to a target creature immediately.<br>
	 * This method updates the PK count for a {@code Player}.<br>
	 * It ensures the new value is not less than 0.
	 * @param effector The creature performing the action.
	 * @param effected The creature receiving the effect.
	 * @param skill The {@code Skill} used to trigger this effect.
	 * @param item The {@code Item} associated with the effect.
	 */
	@Override
	public void instant(Creature effector, Creature effected, Skill skill, Item item)
	{
		final Player player = effected.asPlayer();
		if (player == null)
		{
			return;
		}
		
		if (player.getPkKills() > 0)
		{
			final int newPkCount = Math.max(player.getPkKills() + _amount, 0);
			player.setPkKills(newPkCount);
			player.updateUserInfo();
		}
	}
}
